-- Resolve all active legacy replacement classifications without changing IDs or history.
-- Eligibility describes a browsing family, not equivalent loading or clinical suitability.
begin;
create temporary table legacy_classification as
select * from jsonb_to_recordset($data$[{"slug": "cross_body_cable_y_raise", "name": "Cross-Body Cable Y-Raise", "replacement_family": "scapular_upward_rotation", "equipment_options": [["cable"]], "variant_group": "cross_body_cable_y_raise", "tracking_mode": "reps_each_side", "instructions": ["With a low cable across the body, lift the arm diagonally outward under control; keep the trunk steady."], "source_urls": ["https://www.youtube.com/watch?v=z5lB5z5C0d0"], "catalog_notes": "Single-arm cable variant clarified from the original publisher demonstration. Cable token includes its ordinary handle; attachments such as ropes are separate requirements.", "is_bodyweight": false}, {"slug": "floor_slides", "name": "Supine Shoulder Floor Slides", "replacement_family": "scapular_upward_rotation", "equipment_options": [["bodyweight"]], "variant_group": "supine_shoulder_slide", "tracking_mode": "reps", "instructions": ["Lie face up with bent knees and slide the arms overhead through a comfortable arc, keeping the ribs controlled."], "source_urls": ["https://www.acefitness.org/continuing-education/certified/july-2017/6448/how-to-use-the-ace-integrated-fitness-training-reg-model-to-get-people-moving/"], "catalog_notes": "Legacy shoulder activation record clarified as supine shoulder slides/snow angels; this is low-load scapular control, not an equivalent load to a cable raise.", "is_bodyweight": true}, {"slug": "glute_activation_side_plank_clamshell", "name": "Side-plank Clamshell", "replacement_family": "hip_external_rotation", "equipment_options": [["bodyweight"]], "variant_group": "side_plank_clamshell", "tracking_mode": "reps_each_side", "instructions": ["From a bent-knee side plank, open the upper knee while keeping the feet together and the pelvis controlled."], "source_urls": ["https://www.rjah.nhs.uk/media/e3jmg5t4/pao-rehabilitation-guide.pdf"], "catalog_notes": "Bodyweight base variant; a loop band is optional added resistance. More demanding trunk support than a side-lying clam. Clinical source dosage is not imported.", "is_bodyweight": true}, {"slug": "glute_ham_raise", "name": "Glute-Ham Raise", "replacement_family": "knee_flexion", "equipment_options": [["glute_ham_developer"]], "variant_group": "glute_ham_raise", "tracking_mode": "reps", "instructions": ["Secure the feet in the developer and bend the knees to raise the body, controlling the return without folding at the waist."], "source_urls": ["https://contentcdn.eacefitness.com/February2018/ACE_HamstringsStudy.pdf"], "catalog_notes": "Knee-flexion-dominant developer variant. Requires a fitted glute-ham developer and suitable strength; not equivalent in difficulty to a standing curl.", "is_bodyweight": true}, {"slug": "glute_release_w_lacrosse_ball", "name": "Glute Release with Lacrosse Ball", "replacement_family": "glute_soft_tissue", "equipment_options": [["lacrosse_ball"]], "variant_group": "floor_ball_glute_release", "tracking_mode": "duration_each_side", "instructions": ["Support yourself on the floor and apply controlled ball pressure to the glute soft tissue, avoiding bones and nerve symptoms."], "source_urls": ["https://documents.ucr.edu/HR-Wellness/fswp-move-well-self-myofascial-released-ball.pdf"], "catalog_notes": "Tool-assisted self-massage, not strength volume or a treatment claim. Floor support differs from the wall-ball variant.", "is_bodyweight": false}, {"slug": "kelso_shrug", "name": "Chest-supported Kelso Shrug", "replacement_family": "scapular_retraction", "equipment_options": [["dumbbell", "adjustable_bench"], ["t_bar_row_machine"]], "variant_group": "chest_supported_kelso_shrug", "tracking_mode": "reps", "instructions": ["Support the chest on an incline bench or chest-supported row pad and retract the shoulder blades with the elbows kept straight."], "source_urls": ["https://thatfitfriend.com/kelso-shrugs/"], "catalog_notes": "Chest-supported scapular retraction clarified from the coach-authored guide. The row-machine option requires a chest support; a generic machine token is insufficient.", "is_bodyweight": false}, {"slug": "romanian_deadlift", "name": "Romanian Deadlift", "replacement_family": "hip_hinge", "equipment_options": [["barbell"]], "variant_group": "barbell_rdl", "tracking_mode": "reps", "instructions": ["Begin standing with the bar close to the legs, send the hips back with softly bent knees, then extend the hips to stand."], "source_urls": ["https://www.acefitness.org/continuing-education/certified/may-2025/8865/the-ace-do-it-better-series-the-romanian-deadlift/"], "catalog_notes": "Generic legacy RDL clarified to the traditional barbell variant and grouped with Barbell RDL so the duplicate cannot count as another alternative.", "is_bodyweight": false}, {"slug": "shoulder_dislocations", "name": "Shoulder Pass-through", "replacement_family": "shoulder_mobility", "equipment_options": [["stick"], ["band"]], "variant_group": "shoulder_pass_through", "tracking_mode": "reps", "instructions": ["Use a wide grip and move the stick or light band overhead within a comfortable range; do not force the arms behind you."], "source_urls": ["https://library.crossfit.com/premium/pdf/CFJ_Widman_StartUp3.pdf"], "catalog_notes": "Mobility drill; original misleading slug retained for history. The stick reference establishes the movement; band technique remains an editorial adaptation requiring review.", "is_bodyweight": false}, {"slug": "sissy_squat", "name": "Supported Sissy Squat", "replacement_family": "knee_extension", "equipment_options": [["bodyweight", "doorway"], ["bodyweight", "rack"], ["bodyweight", "stable_counter"]], "variant_group": "sissy_squat", "tracking_mode": "reps", "instructions": ["Hold a fixed support, keep hips extended and bend the knees while the heels rise; use only a controlled range before returning upright."], "source_urls": ["https://barbend.com/sissy-squat/"], "catalog_notes": "Advanced knee-extension-dominant bodyweight movement with a fixed support. Not a dose- or difficulty-equivalent substitute for seated knee extension.", "is_bodyweight": true}, {"slug": "thoracic_extension_release_on_roller", "name": "Thoracic Extension over Roller", "replacement_family": "thoracic_mobility", "equipment_options": [["foam_roller"]], "variant_group": "thoracic_extension_roller", "tracking_mode": "reps", "instructions": ["Support the head and gently extend the upper back over a roller below the shoulder blades without forcing the lower back."], "source_urls": ["https://rightdecisions.scot.nhs.uk/media/alqcguhk/shoulder-rehabilitation-exercises.pdf"], "catalog_notes": "Thoracic mobility with a foam roller; no claim that this releases tissue or treats spinal conditions.", "is_bodyweight": false}, {"slug": "y_raise", "name": "Prone Y-Raise", "replacement_family": "scapular_upward_rotation", "equipment_options": [["bodyweight"]], "variant_group": "prone_y_raise", "tracking_mode": "reps", "instructions": ["Lie face down and lift the arms a little in a Y shape while keeping the neck aligned and trunk controlled."], "source_urls": ["https://www.acefitness.org/resources/everyone/exercise-library/249/prone-scapular-shoulder-stabilization-series-i-y-t-w-o-formation/"], "catalog_notes": "Previously unspecified Y-raise clarified to the unweighted prone variant; weighted/cable variants have separate records.", "is_bodyweight": true}]$data$::jsonb) as r(
 slug text, name text, replacement_family text, equipment_options jsonb,
 variant_group text, tracking_mode text, instructions jsonb, source_urls jsonb,
 catalog_notes text, is_bodyweight boolean);

update public.exercises e set
 name=r.name, replacement_family=r.replacement_family,
 equipment_options=r.equipment_options, variant_group=r.variant_group,
 tracking_mode=r.tracking_mode, instructions=r.instructions,
 source_urls=r.source_urls, catalog_notes=r.catalog_notes,
 is_bodyweight=r.is_bodyweight,
 equipment=(select jsonb_agg(distinct item) from jsonb_array_elements(r.equipment_options) opt cross join lateral jsonb_array_elements(opt) item),
 replacement_status='eligible', replacement_reason=null
from legacy_classification r where e.slug=r.slug;

update public.exercises e set replacement_status=r.status, replacement_reason=r.reason
from (values
('hiit','protocol','An intensity/interval protocol requires a concrete cardio modality and work/rest prescription before movement replacement.'),
('zone_2_cardio','protocol','An intensity target is not a movement; choose walking, cycling or another concrete modality before replacement.'),
('hip_flexion_rotation','sequence','The legacy label combines hip actions without specifying the positions, order or range; retain it for history until its original drill is identified.'),
('hip_stability_lunge_sequence','sequence','Composite lunge sequence has no documented components or order; it cannot be replaced as one defined exercise.'),
('rdl_stability_sequence','sequence','Composite hinge/balance sequence has no documented components or order; it cannot be replaced as one defined exercise.'),
('t_bar_row_kelso_shrug','sequence','Combines a row with a separate scapular shrug; prescribe and replace the components separately.'),
('banded_internal_rotation_stretch','specialist_review','The legacy band-assisted stretch has no documented anchor, body position or force direction; the generic shoulder reference does not establish this technique.'),
('plate_loaded_neck_curls','specialist_review','Loaded neck flexion lacks a validated technique/load prescription in this catalog; anatomy alone does not establish suitability.'),
('db_calf_jumps','specialist_review','The legacy loaded jumping drill has no documented load, landing or progression instructions; review is required before presenting it as a selectable plyometric replacement.')
) as r(slug,status,reason) where e.slug=r.slug;

-- A combination record did not require only a dumbbell as previously claimed.
update public.exercises set equipment='["t_bar_row_machine"]'::jsonb,
 equipment_options='[["t_bar_row_machine"]]'::jsonb,
 catalog_notes='Combined row and scapular shrug sequence on a chest-supported T-bar machine; no automatic replacement.'
where slug='t_bar_row_kelso_shrug';

-- Sissy-squat technique keeps the hip extended; inherited squat glute/hamstring
-- strength credit overstated their role. Correct only this record's associations.
delete from public.exercise_muscle_map where exercise_id=(select id from public.exercises where slug='sissy_squat');
insert into public.exercise_muscle_map(exercise_id,muscle_group_id,role,contribution)
select e.id,m.id,'primary',1 from public.exercises e cross join public.muscle_groups m
where e.slug='sissy_squat' and m.slug='quads';

do $$ begin
 if exists(select 1 from public.exercises where is_active and replacement_status='unreviewed') then
  raise exception 'Active legacy classification is incomplete';
 end if;
end $$;
drop table legacy_classification;
commit;
